cards.solution:
type Prioritas = "rendah" | "sedang" | "tinggi";
type Todo = { readonly id: number; judul: string; selesai: boolean; prioritas: Prioritas };
type Result<T> = { ok: true; data: T } | { ok: false; error: string };
class TodoStore {
  private todos: Todo[] = [];
  private idTerakhir = 0;
  tambah(judul: string, prioritas: Prioritas = "sedang"): Result<Todo> {
    if (judul.trim() === "") return { ok: false, error: "Judul tidak boleh kosong" };
    const t: Todo = { id: ++this.idTerakhir, judul: judul.trim(), selesai: false, prioritas };
    this.todos.push(t);
    return { ok: true, data: t };
  }
  ubahJudul(id: number, judul: string): Result<Todo> {
    if (judul.trim() === "") return { ok: false, error: "Judul tidak boleh kosong" };
    const t = this.todos.find((x) => x.id === id);
    if (!t) return { ok: false, error: `Todo #${id} tidak ada` };
    t.judul = judul.trim();
    return { ok: true, data: t };
  }
}
const store = new TodoStore();
store.tambah("Belajar class");
for (const h of [store.ubahJudul(1, "Belajar generics"), store.ubahJudul(3, "X")]) {
  console.log(h.ok ? h.data.judul : h.error);
}
